use clap::{crate_name, crate_version, App as ClapApp, AppSettings, Arg, ArgGroup, ArgMatches, SubCommand};
use once_cell::sync::Lazy;
use std::collections::{HashMap, HashSet};
use std::env;
use std::ffi::OsString;
use std::io::{self, BufReader, Write};
use std::path::{Path, PathBuf};
use std::str::FromStr;

use crate::assets::{assets_from_cache_or_binary, cache_dir, clear_assets, config_dir};
use crate::config::{
    config_file, generate_config_file, get_args_from_config_file, get_args_from_env_var,
};
use crate::input::{new_file_input, new_stdin_input};

use atty::{self, Stream};
use bat::assets::HighlightingAssets;
use bat::bat_warning;
use bat::config::{get_pager_executable, Config, VisibleLines};
use bat::controller::Controller;
use bat::error::*;
use bat::input::Input;
use bat::line_range::{HighlightedLineRanges, LineRange, LineRanges};
use bat::style::{StyleComponent, StyleComponents};
use bat::{MappingTarget, PagingMode, SyntaxMapping, WrappingMode};
use console::Term;
use globset::GlobMatcher;

static VERSION: Lazy<String> = Lazy::new(|| {
    #[cfg(feature = "bugreport")]
    let git_version = bugreport::git_version!(fallback = "");
    #[cfg(not(feature = "bugreport"))]
    let git_version = "";

    if git_version.is_empty() {
        crate_version!().to_string()
    } else {
        format!("{} ({})", crate_version!(), git_version)
    }
});

const THEME_PREVIEW_DATA: &[u8] = include_bytes!("../../../assets/theme_preview.rs");

pub struct CliEngine {
    cli_interactive: bool,
    paging_interactive: bool,
    style_interactive: bool,
    wrap_interactive: bool,
    raw_args: Vec<OsString>,
    config_tokens: Vec<OsString>,
    config_path: PathBuf,
    config_text: String,
    matches: Option<ArgMatches<'static>>,
    paging_mode: PagingMode,
    pager_spec: Option<String>,
    stdin_present: bool,
    paging_flag: Option<String>,
    extra_plain: bool,
    no_paging_set: bool,
    style_flags: Vec<String>,
    style_set: StyleComponents,
    decorations_never: bool,
    number_set: bool,
    plain_set: bool,
    input_files: Vec<PathBuf>,
    display_names: Vec<Option<PathBuf>>,
    syntax_pairs: Vec<(String, String)>,
    suffix_filters: Vec<String>,
    custom_assets: bool,
    theme_name: String,
    language_listing: String,
    listed_themes: Vec<String>,
}

impl CliEngine {
    pub fn new(interactive_output: bool) -> Self {
        Self {
            cli_interactive: interactive_output,
            paging_interactive: interactive_output,
            style_interactive: interactive_output,
            wrap_interactive: interactive_output,
            raw_args: Vec::new(),
            config_tokens: Vec::new(),
            config_path: PathBuf::new(),
            config_text: String::new(),
            matches: None,
            paging_mode: PagingMode::Never,
            pager_spec: None,
            stdin_present: false,
            paging_flag: None,
            extra_plain: false,
            no_paging_set: false,
            style_flags: Vec::new(),
            style_set: StyleComponents(HashSet::new()),
            decorations_never: false,
            number_set: false,
            plain_set: false,
            input_files: Vec::new(),
            display_names: Vec::new(),
            syntax_pairs: Vec::new(),
            suffix_filters: Vec::new(),
            custom_assets: true,
            theme_name: String::new(),
            language_listing: String::new(),
            listed_themes: Vec::new(),
        }
    }

    pub fn from_matches(matches: ArgMatches<'static>, interactive_output: bool) -> Self {
        let mut engine = Self::new(interactive_output);
        engine.matches = Some(matches);
        engine
    }

    pub fn parse_matches(&mut self) -> Result<ArgMatches<'static>> {
        self.collect_raw_invocation_args()?;
        let matches = self.compose_clap_app().get_matches_from(self.raw_args.clone());
        self.matches = Some(matches.clone());
        Ok(matches)
    }

    fn cache_or_noconfig_requested(&self) -> bool {
        if self.raw_args.iter().any(|arg| arg == "--no-config") {
            true
        } else if self.raw_args.get(1).map(|arg| arg == "cache").unwrap_or(false) {
            true
        } else {
            wild::args_os().nth(1) == Some("cache".into())
                || wild::args_os().any(|arg| arg == "--no-config")
        }
    }

    fn collect_raw_invocation_args(&mut self) -> Result<()> {
        self.raw_args = wild::args_os().collect::<Vec<_>>();
        if self.cache_or_noconfig_requested() {
            self.config_tokens.clear();
            self.config_text.clear();
            return Ok(());
        }
        self.load_config_path();
        self.load_config_text();
        self.load_env_or_file_tokens()?;
        self.merge_program_name_and_cli();
        let _ = (
            self.config_text_has_paging_always(),
            self.config_text_has_paging_never(),
            self.count_config_tokens(),
        );
        Ok(())
    }

    fn load_config_path(&mut self) {
        self.config_path = config_file();
        if self.config_path.as_os_str().is_empty() {
            self.config_path = PathBuf::from("config");
        }
    }

    fn load_config_text(&mut self) {
        self.config_text = std::fs::read_to_string(&self.config_path).unwrap_or_default();
        if self.config_text.starts_with('\u{feff}') {
            self.config_text = self.config_text.trim_start_matches('\u{feff}').to_string();
        }
    }

    fn load_env_or_file_tokens(&mut self) -> Result<()> {
        match get_args_from_env_var() {
            Some(Ok(tokens)) => {
                self.config_tokens = tokens;
                Ok(())
            }
            Some(Err(_)) => Err("Could not parse configuration file".into()),
            None => match get_args_from_config_file() {
                Ok(tokens) => {
                    self.config_tokens = tokens;
                    Ok(())
                }
                Err(_) => Err("Could not parse configuration file".into()),
            },
        }
    }

    fn merge_program_name_and_cli(&mut self) {
        let mut cli_args = wild::args_os();
        self.raw_args = self.config_tokens.clone();
        if let Some(program) = cli_args.next() {
            self.raw_args.insert(0, program);
        }
        for arg in cli_args {
            self.raw_args.push(arg);
        }
    }

    fn config_path_display(&self) -> String {
        if self.config_path.as_os_str().is_empty() {
            config_file().to_string_lossy().into_owned()
        } else {
            self.config_path.to_string_lossy().into_owned()
        }
    }

    fn config_text_has_paging_always(&self) -> bool {
        self.config_text.lines().any(|line| {
            let trimmed = line.trim();
            !trimmed.starts_with('#') && trimmed.contains("--paging=always")
        })
    }

    fn config_text_has_paging_never(&self) -> bool {
        self.config_text.lines().any(|line| {
            let trimmed = line.trim();
            !trimmed.starts_with('#') && (trimmed.contains("--paging=never") || trimmed == "-P")
        })
    }

    fn count_config_tokens(&self) -> usize {
        if self.config_tokens.is_empty() && self.config_text.is_empty() {
            0
        } else if self.config_tokens.is_empty() {
            self.config_text
                .lines()
                .filter(|line| !line.trim().is_empty() && !line.trim().starts_with('#'))
                .count()
        } else {
            self.config_tokens.len()
        }
    }

    pub fn generate_user_config(&mut self) -> Result<()> {
